script:
(function () {
  'use strict';
  // College savings projection. Monthly compounding at (annual return / 12); contributions at the
  // end of each month until enrollment, then stop. Each college year's cost is paid at the start of
  // that year and grows with education cost inflation:
  //   cost(k) = annual cost today x share covered x (1 + inflation)^(years to college + k), k = 0..N-1
  //   savings at enrollment = saved x (1+i)^M + monthly x ((1+i)^M - 1) / i,   i = r/12, M = 12 x years
  //   monthly needed = (PV of costs at enrollment - saved x (1+i)^M) / (((1+i)^M - 1) / i)
  //   PV of costs at enrollment = sum of cost(k) / (1+i)^(12k)
  // Verified (Node scratch test against an independent Python calculation): $25,000 a year today,
  // 5% cost inflation, 12 years to college, 4 years of study, $10,000 saved, $300 a month, 6% return
  // -> yearly costs $44,896 / $47,141 / $49,498 / $51,973 (total $193,509), savings at enrollment
  // $83,553, shortfall $107,572, monthly saving needed $742.98; re-running at $742.98 a month pays
  // all four years and leaves about $1. With 0% return and 0% inflation, $10,000 x 4 years in
  // 10 years needs $333.33 a month (= $40,000 / 120). Years to college = 0, zero cost, zero and
  // invalid inputs checked: no NaN or Infinity reaches the page.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 0 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function plan(o) {
    var i = o.ret / 12, M = o.yearsTo * 12, costs = [], total = 0, pv = 0, k, m, y;
    for (k = 0; k < o.yearsIn; k++) {
      var c = o.cost * o.share * Math.pow(1 + o.infl, o.yearsTo + k);
      costs.push(c);
      total += c;
      pv += c / Math.pow(1 + i, 12 * k);
    }
    var grow = Math.pow(1 + i, M);
    var annuity = i === 0 ? M : (grow - 1) / i;
    var fvSaved = o.saved * grow;
    var atEnroll = fvSaved + o.monthly * annuity;
    var needed = M > 0 ? Math.max(0, (pv - fvSaved) / annuity) : null;

    var rows = [], bal = o.saved, unfunded = 0, contributedTotal = o.saved;
    for (y = 1; y <= o.yearsTo; y++) {
      var start = bal;
      for (m = 0; m < 12; m++) bal = bal * (1 + i) + o.monthly;
      contributedTotal += 12 * o.monthly;
      rows.push({ year: y, stage: 'Saving', contrib: 12 * o.monthly, paid: 0, growth: bal - start - 12 * o.monthly, balance: bal });
    }
    for (k = 0; k < o.yearsIn; k++) {
      var startC = bal;
      var paid = Math.min(bal, costs[k]);
      unfunded += costs[k] - paid;
      bal -= paid;
      if (bal < 1e-6) bal = 0;
      bal = bal * Math.pow(1 + i, 12);
      rows.push({ year: o.yearsTo + k + 1, stage: 'College year ' + (k + 1), contrib: 0, paid: paid, growth: bal - startC + paid, balance: bal });
    }
    return { costs: costs, total: total, pv: pv, atEnroll: atEnroll, needed: needed, unfunded: unfunded,
             leftover: bal, contributed: contributedTotal, rows: rows };
  }

  function cell(tr, text) {
    var td = document.createElement('td');
    td.textContent = text;
    tr.appendChild(td);
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var o = {
      cost: num('csCost'), infl: num('csInflation') / 100, yearsTo: num('csYearsTo'), yearsIn: num('csYearsIn'),
      share: num('csShare') / 100, saved: num('csSaved'), monthly: num('csMonthly'), ret: num('csReturn') / 100
    };
    var error = document.getElementById('csError');
    var bad = [o.cost, o.infl, o.yearsTo, o.yearsIn, o.share, o.saved, o.monthly, o.ret].some(isNaN) ||
      o.cost < 0 || o.saved < 0 || o.monthly < 0 || o.infl < 0 || o.infl > 0.2 || o.ret < 0 || o.ret > 0.3 ||
      o.yearsTo < 0 || o.yearsTo > 30 || o.yearsTo !== Math.floor(o.yearsTo) ||
      o.yearsIn < 1 || o.yearsIn > 8 || o.yearsIn !== Math.floor(o.yearsIn) || o.share < 0 || o.share > 1;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter non-negative amounts, 0 to 30 whole years until college, 1 to 8 years of study, ' +
        'cost inflation up to 20%, a return up to 30% and a share from 0 to 100%.';
      return;
    }
    var r = plan(o);
    set('csNeeded', r.needed === null ? 'n/a' : money.format(r.needed));
    set('csNeededNote', r.needed === null
      ? 'College starts this year, so there is no time left for monthly saving.'
      : (r.needed <= o.monthly
        ? 'Your current plan already covers the projected costs.'
        : 'That is ' + money.format(r.needed - o.monthly) + ' a month more than you save now.'));
    set('csTotal', money.format(r.total));
    set('csAtEnroll', money.format(r.atEnroll));
    if (r.unfunded > 0.5) {
      set('csGapLabel', 'Projected shortfall');
      set('csGap', money.format(r.unfunded));
    } else {
      set('csGapLabel', 'Left over after college');
      set('csGap', money.format(r.leftover));
    }
    set('csFirstYear', r.costs.length ? money.format(r.costs[0]) : '–');
    set('csCovered', pct.format(r.total > 0 ? (r.total - r.unfunded) / r.total : 1));
    set('csContributed', money.format(r.contributed));

    var body = document.getElementById('csSchedule');
    while (body.firstChild) body.removeChild(body.firstChild);
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      cell(tr, String(row.year));
      cell(tr, row.stage);
      cell(tr, money.format(row.contrib));
      cell(tr, money.format(row.growth));
      cell(tr, money.format(row.paid));
      cell(tr, money.format(row.balance));
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('csForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
